<script>
    import { onMount } from 'svelte';
    export let api; export let state; export let datasets = []; export let saveDownload;
    let targets = [], datasetId = '', purpose = 'overall', targetId = '', exposure = '', prefix = '', prefixTouched = false, format = 'csv';
    let loading = true, error = '', check = null, preview = null, downloadMetadata = null, checking = false, downloading = false, request = 0, lastSelection = '', lastChoice = '';
    $: readyDatasets = datasets.filter((item) => item.status === 'available');
    $: if (!readyDatasets.some((item) => item.id === datasetId)) datasetId = readyDatasets[0]?.id || '';
    $: dataset = readyDatasets.find((item) => item.id === datasetId);
    $: primaryTargets = targets.filter((item) => item.purpose === purpose);
    $: ratingTargets = targets.filter((item) => item.purpose === 'rating');
    $: selectedTarget = targets.find((item) => item.id === targetId);
    $: candidates = targets.filter((item) => item.purpose === 'candidate' && item.candidate_for === targetId);
    $: candidateTarget = selectedTarget?.purpose === 'candidate' ? selectedTarget : null;
    $: baseTarget = candidateTarget ? targets.find((item) => item.id === candidateTarget.candidate_for) : selectedTarget;
    $: requiredColumns = selectedTarget?.required_columns || [];
    $: availableColumns = new Set((dataset?.columns || []).map((item) => item.name));
    $: missingColumns = requiredColumns.filter((column) => !availableColumns.has(column));
    $: exposureOptions = (['overall', 'checkpoint'].includes(selectedTarget?.purpose) ? selectedTarget?.allowed_exposure_columns ?? [] : []).filter((column) => availableColumns.has(column));
    $: if (exposure && !exposureOptions.includes(exposure)) exposure = '';
    $: suggestedPrefix = `easyglm_${(selectedTarget?.label || 'score').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '').toLowerCase()}_`;
    $: if (!prefixTouched) prefix = suggestedPrefix;
    $: choiceKey = `${datasetId}|${targetId}`;
    $: if (choiceKey !== lastChoice) { lastChoice = choiceKey; exposure = ''; }
    $: payload = { session_id: state?.session_id, revision: state?.revision, dataset_id: datasetId, model_id: selectedTarget?.request?.model_id, scope: selectedTarget?.request?.scope, component_ids: selectedTarget?.request?.component_ids || [], through: selectedTarget?.request?.through || null, exposure_col: exposure || null, column_prefix: prefix || suggestedPrefix };
    $: summaryOutput = exposure ? (selectedTarget?.expected_label || `Expected amount using ${exposure}`) : (selectedTarget?.output_label || selectedTarget?.output_kind || 'score');
    $: includedNames = selectedTarget?.included_models || [];
    $: targetSummaryName = selectedTarget?.purpose === 'candidate' ? selectedTarget?.label : (includedNames.join(' + ') || selectedTarget?.label || 'selected scoring target');
    $: scoreSummary = `Score ${dataset?.name || 'dataset'} using ${targetSummaryName} → ${summaryOutput}`;
    $: scoreDetails = { dataset: dataset ? { id: dataset.id, name: dataset.name, filename: dataset.filename, digest: dataset.digest, version: dataset.version } : null, selected_target: selectedTarget ? { id: selectedTarget.id, label: selectedTarget.label, purpose: selectedTarget.purpose, model_name: selectedTarget.model_name, saved_version: selectedTarget.saved_version, included_models: selectedTarget.included_models } : null, output: { summary: scoreSummary, request: payload, exposure_column: payload.exposure_col }, frozen_score: downloadMetadata || preview?.metadata?.pinned || check?.pinned || null, preflight_warnings: check?.warnings || [], preview_warnings: preview?.warnings || [] };
    $: checkReady = check?.ready === true && !(check?.issues || []).length;
    $: selectionKey = `${state?.revision}|${datasetId}|${dataset?.digest}|${dataset?.version}|${purpose}|${targetId}|${exposure}|${prefixTouched ? prefix : ''}`;
    $: if (selectionKey !== lastSelection) { lastSelection = selectionKey; request += 1; check = null; preview = null; downloadMetadata = null; checking = false; }
    function selectPurpose(next) { exposure = ''; purpose = next; targetId = targets.find((item) => item.purpose === next)?.id || ''; }
    function selectTarget(event) { const id = event.currentTarget.value; if (!id) return; const next = targets.find((item) => item.id === id); if (!next) return; exposure = ''; if (next.purpose !== 'candidate') purpose = next.purpose; targetId = id; }
    function selectCandidate(candidate) { exposure = ''; purpose = 'rating'; targetId = candidate.id; }
    function savedAt(value) { if (!value) return 'saved date unavailable'; const date = new Date(value); return Number.isNaN(date.valueOf()) ? 'saved date unavailable' : new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).format(date); }
    function targetOptionLabel(item) {
        const base = item.purpose === 'overall' ? (item.included_models || []).join(' + ') || item.model_name : item.label;
        const sameLabel = (other) => (other.purpose === 'overall' ? (other.included_models || []).join(' + ') || other.model_name : other.label) === base;
        const matching = targets.filter((other) => other.purpose === item.purpose && sameLabel(other));
        const sameMinute = matching.filter((other) => savedAt(other.created_at) === savedAt(item.created_at));
        if (item.purpose === 'overall' || matching.length > 1) {
            return sameMinute.length > 1 ? `${base} · saved as ${item.model_name} · ${savedAt(item.created_at)}` : `${base} · saved ${savedAt(item.created_at)}`;
        }
        return base;
    }
    function issueText(issue) { if (typeof issue === 'string') return issue; const fields = issue.columns || issue.column || issue.values || issue.examples; return [issue.message || issue.detail || 'Input cannot be used for this saved score.', fields ? Array.isArray(fields) ? fields.join(', ') : fields : '', issue.dependency ? `Required by ${issue.dependency}.` : ''].filter(Boolean).join(' '); }
    async function load() { loading = true; try { const response = await api('scoring/models'); targets = response.targets || []; targetId = targets.find((item) => item.purpose === 'overall')?.id || ''; } catch (event) { error = event.message; } finally { loading = false; } }
    async function checkInputs(previewOnly = false) { if (!datasetId || !selectedTarget?.request?.model_id) return; const active = ++request; checking = true; error = ''; try { const result = await api(previewOnly ? 'scoring/preview' : 'scoring/check', structuredClone(payload)); if (active !== request) return; if (previewOnly) preview = result; else { check = result; preview = null; } } catch (event) { if (active === request) error = event.message; } finally { if (active === request) checking = false; } }
    async function download() { if (!checkReady || downloading) return; const active = ++request, frozenPayload = structuredClone(payload), frozenDetails = structuredClone(scoreDetails); downloading = true; error = ''; try { const file = await api(`scoring/export?format=${encodeURIComponent(format)}`, frozenPayload, true); if (active !== request) return; saveDownload(file.blob, file.filename); downloadMetadata = file.scoringMetadata ? JSON.parse(file.scoringMetadata) : null; if (downloadMetadata) downloadDetails(`${file.filename}.metadata.json`, downloadMetadata, frozenDetails); } catch (event) { if (active === request) error = event.message; } finally { if (active === request) downloading = false; } }
    function downloadDetails(filename = '', frozen = null, details = scoreDetails) { const name = filename || `${dataset?.name || 'scoring'}_${selectedTarget?.label || 'target'}_score_details.json`.replace(/[^A-Za-z0-9._-]+/g, '_'); saveDownload(new Blob([JSON.stringify({ ...details, frozen_score: frozen || details.frozen_score }, null, 2)], { type: 'application/json' }), name); }
    onMount(load);
</script>

<section class="workflow-page score-new-data">
    <div class="heading"><div><h1>Score on new data</h1><p>Use fitted models to score another dataset. This does not refit or change the accepted chain.</p></div></div>
    {#if error}<div class="message error" role="alert">{error}</div>{/if}
    {#if loading}<p>Loading scoring targets…</p>
    {:else if !readyDatasets.length || !targets.length}<section class="model-card"><h2>{!readyDatasets.length ? 'Add a scoring dataset' : 'Fit and save a model first'}</h2><p>{!readyDatasets.length ? 'Go to Project & data and add a separate CSV or Parquet scoring dataset.' : 'A saved model is needed before this dataset can be scored.'}</p></section>
    {:else}
        <section class="model-card score-section"><h2><span>1</span>Dataset</h2><label>Scoring dataset<select aria-label="Scoring dataset" bind:value={datasetId}>{#each readyDatasets as item}<option value={item.id}>{item.name}</option>{/each}</select></label>{#if dataset}<p class="score-summary"><strong>{dataset.name}</strong> · {dataset.rows?.toLocaleString()} rows · {dataset.columns?.length} columns</p>{/if}</section>
        <section class="model-card score-section">
            <h2><span>2</span>What do you want to produce?</h2>
            <fieldset><legend>Choose a purpose</legend><div class="purpose-options">
                <label class:chosen={purpose === 'overall'}><input name="scoring-purpose" type="radio" checked={purpose === 'overall'} onchange={() => selectPurpose('overall')} /><strong>Overall prediction</strong><span>Score the complete saved result.</span></label>
                {#if ratingTargets.length}<label class:chosen={purpose === 'rating'}><input name="scoring-purpose" type="radio" checked={purpose === 'rating'} onchange={() => selectPurpose('rating')} /><strong>One rating model</strong><span>Score one named rating model.</span></label>{/if}
            </div></fieldset>
            {#if purpose === 'checkpoint'}
                <p class="advanced-active"><strong>Advanced checkpoint selected:</strong> {selectedTarget?.label} <button onclick={() => selectPurpose('overall')}>Return to standard choices</button></p>
            {:else}
                <label>{purpose === 'overall' ? 'Pricing model' : 'Rating model'}<select aria-label={purpose === 'overall' ? 'Pricing model' : 'Rating model'} value={baseTarget?.id || targetId} onchange={selectTarget}>{#each primaryTargets as item}<option value={item.id}>{targetOptionLabel(item)}</option>{/each}</select></label>
            {/if}
            {#if purpose === 'rating' && candidates.length}<div class="candidate-panel"><strong>Accepted lookup is selected</strong><p>The accepted target remains the default. A refreshed master is a separate review-only candidate.</p>{#each candidates as candidate}<button onclick={() => selectCandidate(candidate)}>Score refreshed catalogue master: {candidate.label}</button>{/each}</div>{/if}
            {#if candidateTarget}<p class="candidate-selected"><strong>Candidate catalogue output selected.</strong> Review only; it cannot replace the accepted lookup or chain. <button onclick={() => (targetId = candidateTarget.candidate_for)}>Use accepted lookup instead</button></p>{/if}
            <details class="advanced-targets"><summary>Advanced cumulative checkpoints</summary><label>Checkpoint<select aria-label="Advanced cumulative checkpoint" value={purpose === 'checkpoint' ? targetId : ''} onchange={selectTarget}><option value="">Choose a checkpoint</option>{#each targets.filter((item) => item.purpose === 'checkpoint') as item}<option value={item.id}>{targetOptionLabel(item)}</option>{/each}</select></label></details>
            <details class="details"><summary>Details and output settings</summary><p>Fitted model: {selectedTarget?.model_name}</p>{#if selectedTarget?.created_at}<p>Saved: {savedAt(selectedTarget.created_at)}</p>{/if}<p>Included models: {includedNames.join(' + ') || selectedTarget?.model_name}</p><label>Output column prefix <input aria-label="Output column prefix" placeholder={suggestedPrefix} bind:value={prefix} oninput={() => (prefixTouched = true)} /></label></details>
        </section>
        <section class="model-card score-section readiness-section"><h2><span>3</span>Inputs and output</h2><p class="score-statement" aria-live="polite">{scoreSummary}</p><div class:missing={missingColumns.length} class="structural-check"><strong>{missingColumns.length ? 'Missing required columns' : 'Required columns: all present'}</strong><p>{missingColumns.length ? missingColumns.join(', ') : (requiredColumns.join(', ') || 'No additional columns required for this saved model.')}</p>{#if !missingColumns.length}<p>Check values and keys before scoring.</p>{/if}</div>{#if ['frequency', 'rate'].includes(selectedTarget?.output_kind) && exposureOptions.length}<label>Prediction basis<select aria-label="Prediction basis" bind:value={exposure}><option value="">Unit prediction — per unit exposure / policy-period response</option>{#each exposureOptions as column}<option value={column}>{selectedTarget.expected_label || `Expected amount using ${column} once from this scoring book`}</option>{/each}</select></label>{:else if selectedTarget?.output_kind === 'probability'}<p class="help-text">This target returns a probability. Expected amount is unavailable.</p>{/if}<button class="primary" onclick={() => checkInputs()} disabled={checking}>{checking ? 'Checking inputs…' : 'Check inputs'}</button>{#if check}<div class:failed={!checkReady} class="check-result"><strong>{!checkReady ? 'Cannot score this dataset yet' : `Ready to score ${(check.rows || dataset?.rows || 0).toLocaleString()} rows`}</strong><p>{check.message || (!checkReady ? 'Fix the listed inputs, then check again.' : 'Values and lookup coverage are ready for this saved score.')}</p>{#if check.issues}{#each check.issues as issue}<p class="issue"><strong>{issue.category || issue.kind}</strong> {issueText(issue)}</p>{/each}{/if}{#if check.warnings}{#each check.warnings as warning}<p class="warning"><strong>{warning.category || warning.kind || 'Lookup coverage'}</strong> {issueText(warning)}</p>{/each}{/if}</div>{/if}{#if checkReady}<button onclick={() => checkInputs(true)} disabled={checking}>Preview first 20 rows</button>{/if}{#if preview}<div class="score-preview"><h3>{candidateTarget ? 'Candidate catalogue output' : 'Score preview'}</h3><p class="score-statement">{scoreSummary}</p><p>First 20 rows in source order. Original columns are retained.</p>{#if preview.warnings?.length}{#each preview.warnings as warning}<p class="warning"><strong>{warning.category || warning.kind || 'Score warning'}</strong> {issueText(warning)}</p>{/each}{/if}<div class="preview-scroll"><table><thead><tr>{#each preview.columns || [] as column}<th>{column}</th>{/each}</tr></thead><tbody>{#each preview.rows || [] as row}<tr>{#each preview.columns || [] as column}<td>{row[column]}</td>{/each}</tr>{/each}</tbody></table></div><label>File format <span><input type="radio" bind:group={format} value="csv" /> CSV</span><span><input type="radio" bind:group={format} value="parquet" /> Parquet</span></label><div class="download-actions"><button class="primary" onclick={download} disabled={downloading}>{downloading ? 'Preparing download…' : 'Download scored data'}</button><button onclick={() => downloadDetails()}>Download score details</button></div><p class="help-text">Records the exact saved model, scoring dataset and selected output.</p></div>{/if}</section>
    {/if}
</section>

<style>
    .score-new-data { max-width:1100px; }.score-section { display:grid; gap:14px; }.score-section h2 span { display:inline-grid; place-items:center; width:22px; height:22px; margin-right:8px; border-radius:50%; background:#e3ebe6; color:#123e2d; font-size:12px; }.score-section > label,.details label,.advanced-targets label { display:grid; gap:6px; max-width:720px; font-size:13px; }.score-section select,.score-section input { width:100%; }.score-summary,.check-result,.structural-check { margin:0; padding:12px; background:var(--surface-muted); border-radius:6px; }.purpose-options { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; max-width:760px; }.purpose-options label { display:grid; grid-template-columns:18px 1fr; gap:3px 9px; padding:12px; border:1px solid var(--border); border-radius:6px; }.purpose-options label span { grid-column:2; color:var(--muted); }.purpose-options label.chosen { border-color:#156347; background:#e6f2eb; }.candidate-panel,.candidate-selected { padding:12px; border:1px solid #c49a3d; background:#fffaf0; border-radius:6px; }.candidate-panel p { margin:5px 0 10px; }.candidate-selected { color:#6e551c; }.candidate-selected button { margin-left:8px; }.advanced-targets,.details { display:grid; gap:10px; }.score-statement { margin:0; padding:12px; border-left:4px solid #156347; background:#e6f2eb; color:#123e2d; font-weight:600; }.structural-check.missing,.check-result.failed { background:#fff1e9; }.issue { color:#8b4215; }.warning { padding:8px 10px; background:#fff6dd; color:#6e551c; border-left:3px solid #c49a3d; }.score-preview { display:grid; gap:12px; }.preview-scroll { overflow:auto; max-width:100%; border:1px solid var(--border); }.preview-scroll table { border-collapse:collapse; min-width:max-content; width:100%; }.preview-scroll th,.preview-scroll td { padding:7px 10px; border-bottom:1px solid var(--border); text-align:left; white-space:nowrap; }.preview-scroll th { background:var(--surface-muted); }.score-preview > label { display:flex; align-items:center; gap:10px; }.download-actions { display:flex; gap:8px; flex-wrap:wrap; } @media (max-width:797px) { .purpose-options { grid-template-columns:1fr; }.score-section > label,.details label,.advanced-targets label { max-width:none; }.score-preview > label { flex-wrap:wrap; }.score-preview button,.score-section > button { width:100%; }.download-actions { display:grid; }.download-actions button { width:100%; }.candidate-selected button { margin:8px 0 0; } }
</style>
